def feed_schedule(t):
    """Feed rate doubles after t=500."""
    base = make_stream({"A": 1.0, "B": 0.0}, T=350.0, P=101325.0)
    if t > 500:
        return {k: v * 2 for k, v in base.items()}
    return base

